      if(existingGuest&&registrations.some(r=>r.tournament_id===regTour.id&&r.player_id===existingGuest.id&&r.present))return $('#publicRegStatus').textContent='Cet invitÃ© est dÃ©jÃ  inscrit Ã  cette Ã©dition.';
