      if(error||!data){codeStatus.textContent=error?.message||'Code Ã©quipe invalide ou non autorisÃ©. Demande ton code Ã  lâ€™administrateur.';formAfterCode.classList.add('hidden');validatedTeamCode='';return}
      validatedTeamCode=code;
