    '#16a34a':['Vert','Verts','Verte','Vertes'],
    '#eab308':['Jaune','Jaunes'],
    '#f97316':['Orange','Oranges'],
    '#7c3aed':['Violet','Violets','Violette','Violettes'],
    '#ec4899':['Rose','Roses'],
