    const waiting=sessionRegs.filter(r=>r.registration_status==='waitlist').length;
    const leagueMembers=players.filter(pl=>pl.active&&confirmedLeagueIds.has(pl.id)).sort((a,b)=>a.name.localeCompare(b.name));

