    const latestSession=played.length?played[played.length-1]:null;
    const latestMatch=latestSession?(leagueMatches.filter(m=>m.tournament_id===latestSession.id).pop()||null):null;

    let lastSweHtml='<div class="card" style="background:#f8fbf9"><h2 class="sectiontitle">ğŸ”¥ Dernier SwÃ© de la Ligue</h2><p class="muted">Aucun match nâ€™a encore Ã©tÃ© jouÃ© dans cette Ligue. Aucune Ã©quipe de tournoi nâ€™est affichÃ©e.</p></div>';
